-- 199: Original BrillaPrep WASSCE BrillaPrep transitional Basketry beta content blueprint questions, part 7.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_199_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_199_guard;
INSERT INTO _migration_199_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_025' AND NOT (q.topic_id IS 'topic_was_basketry_b004_5' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why should a prototype be made before producing a new basket design in quantity?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It mainly serves as a colour sample and may omit the proposed construction","B. It fixes the price without recording material, labour or overhead","C. It tests dimensions, construction, appearance and fitness for purpose before repeated production","D. It makes inspection of later units unnecessary once the first looks sound"]' AND q.correct_answer IS 'C' AND q.explanation IS 'A prototype combines the intended form, materials and technique so the maker can identify structural, ergonomic and visual weaknesses before they are repeated across a production run. Therefore the correct answer is C: It tests dimensions, construction, appearance and fitness for purpose before repeated production.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_5' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_025' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_199_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_026' AND NOT (q.topic_id IS 'topic_was_basketry_b004_6' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why must a woven basket base be checked for shape and flatness before the sides are raised?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Postpone all base correction until after the rim locks the stakes","B. Accept a rocking base as a deliberate sign of hand production","C. Raise the sides first because their tension will flatten any twisted base","D. Errors in the base will influence the alignment and stability of the whole form"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The base establishes the stake spacing and footprint, so early correction prevents a persistent lean, rocking product or unequal wall circumference that becomes harder to remedy later. Therefore the correct answer is D: Errors in the base will influence the alignment and stability of the whole form.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_6' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_026' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_199_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_027' AND NOT (q.topic_id IS 'topic_was_basketry_b004_6' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What does upsetting the stakes mean during stake-and-strand construction?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Cut the base stakes flush before any wall weaving begins","B. Complete and bind the rim before changing the direction of the stakes","C. Bend the horizontal weavers upward while leaving all stakes flat","D. Bending the base stakes upward to establish the side walls"]' AND q.correct_answer IS 'D' AND q.explanation IS 'After the base reaches its planned size, the stakes are conditioned and turned upward in a controlled manner so weaving can continue around the emerging wall without splitting them. Therefore the correct answer is D: Bending the base stakes upward to establish the side walls.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_027' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_199_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_028' AND NOT (q.topic_id IS 'topic_was_basketry_b004_6' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which statement correctly distinguishes fitching from finishing in basketry?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Fitching is close one-strand randing used to fill the wall, while finishing means raising the stakes from the base","B. Fitching forms a square-knot handle from cords, while finishing colours unsized materials before construction","C. Fitching is planned open-work twining around stakes, while finishing secures, trims and refines the completed basket","D. Fitching locks the final border around cut stake ends, while finishing creates spaced open rows through the wall"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Fitching is an open-work weave commonly worked with two weavers in a twining or pairing action, with deliberate spaces between rows. Finishing is the later securing, trimming, smoothing and suitable surface treatment of the whole product. Therefore the correct answer is C: Fitching is planned open-work twining around stakes, while finishing secures, trims and refines the completed basket.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_028' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_025', 'topic_was_basketry_b004_5', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'Why should a prototype be made before producing a new basket design in quantity?', 'multiple_choice', NULL, '["A. It mainly serves as a colour sample and may omit the proposed construction","B. It fixes the price without recording material, labour or overhead","C. It tests dimensions, construction, appearance and fitness for purpose before repeated production","D. It makes inspection of later units unnecessary once the first looks sound"]', 'C', 'A prototype combines the intended form, materials and technique so the maker can identify structural, ergonomic and visual weaknesses before they are repeated across a production run. Therefore the correct answer is C: It tests dimensions, construction, appearance and fitness for purpose before repeated production.', 'easy', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_5', 'Explain', 'AO1', NULL, NULL, 'board_waec');
