INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_027', 'topic_was_basketry_b004_6', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'What does upsetting the stakes mean during stake-and-strand construction?', 'multiple_choice', NULL, '["A. Cut the base stakes flush before any wall weaving begins","B. Complete and bind the rim before changing the direction of the stakes","C. Bend the horizontal weavers upward while leaving all stakes flat","D. Bending the base stakes upward to establish the side walls"]', 'D', 'After the base reaches its planned size, the stakes are conditioned and turned upward in a controlled manner so weaving can continue around the emerging wall without splitting them. Therefore the correct answer is D: Bending the base stakes upward to establish the side walls.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_6', 'Identify', 'AO3', NULL, NULL, 'board_waec');
